/* ====== 全局字体====== */


/* 导入英文字体 ZSFT-720 */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-720%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2F720%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");

/* 导入中文字体 KingHwaOldSong */
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "ZSFT-720", "KingHwaOldSong", sans-serif;
    font-weight: normal;
}
/*———————— 顶栏 ————————*/
#top-bar {
    position: fixed !important;  
    overflow: visible !important;
    background: none !important;
    border: 0 !important;
    box-shadow: none !important;
    pointer-events: none;
    width: 100vw;  /*宽度*/
    height: 100px;  
    top: 0;
    left: 0;
}

#top-bar::before {
    content: "";
    position: fixed;
    background:  url("https://iili.io/qRq3iQ4.png") no-repeat center / cover;  

    /*⭕️顶栏核心 */
    top: 0px;
    left: 0px;
    right: 0px;
    bottom: 50px;/*⭕️只有这里需要改*/


    z-index: 5;
    pointer-events: auto;

    transform: none !important;
    animation: none !important;
}


/* —————面板背景———— */
.drawer-content {
 background-image: url('https://iili.io/qRq3BIf.png'); /* 面板背景 */
  background-size: cover; 
  background-position: center; 
  background-repeat: no-repeat; 
  background-attachment: fixed; 
}


/* ===== ⭕️楼层箭头、计数器核心 ===== */
.fa-chevron-right:before,
.fa-chevron-left:before,
.fa-arrow-right:before {
  content: "" !important;
  display: none !important; 
}

.fa-chevron-left,
.fa-chevron-right {
  display: inline-block;
  width: 30px;
  height: 30px; 
  min-width: 0;
  opacity: 1 !important; 
  background: center/contain no-repeat;
opacity: 1 !important;

}

.fa-chevron-left {
  background-image: url('https://iili.io/qRq3Xpa.png'); /* 左 */
  margin-bottom: -58px; 

padding: 0px 8px 0;
}
.fa-chevron-right {
  background-image: url('https://iili.io/qRq3VYF.png'); /* 右 */
  top: 50% !important;
  left: 0% !important;
  transform: translate(-60%, 127%) !important;
  z-index: 9999 !important;
}
/* ===== 楼层计数器样式 ===== */
.swipes-counter {
  font-size: 8px;
  font-weight: 540;
  opacity: 0.6 !important;
  color: #ffefc9 !important;

transform: rotate(0deg); /* 旋转 */
}
.swipes-counter {
  position: absolute;
  top: 48px;
  right: 56px;
  z-index: 9999;
  pointer-events: none;
}

/* ==============================================
🦋气泡拼接开始🦋 *==============================================*/


/* 🍃上层装饰层、拼接气泡顶部 */
.mes::before {
  content: "";
  position: absolute;
  top: -46px; /* 【上下】(负值向上) */
  left: 0%; /* 左右 */
  width: 358px; /* 【宽度/大小】 */
  height: 400px; /* 【高度/大小】 */
  background-image: url('https://iili.io/qRq3cLQ.png'); 
  background-size: contain; 
  background-repeat: no-repeat; 
  z-index: -2; 
  pointer-events: none; 
}


/* 🍃 中层气泡*/
.mes {
   z-index: -3;
  max-width: 358px;/*【🍃宽度】*/
  width: 100%;/*【👁宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 65px auto 80px;/*【AI和用户的气泡距离⭕️第一个是调整最早的消息与顶部的距离防止顶部超过屏幕】*/
  border-radius: 0px;
  background: url('https://iili.io/qRq3HqN.png') repeat-y; 
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  position: relative;
  overflow: visible;
  box-shadow: none !important; 
}


/* 🍃下层装饰层、拼接气泡尾部 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -140px; /* 【上下】(负值向下) */
  left: 0%; /* 左右 */
  width: 358px; /* 【宽度/大小】 */
  height: 152px; /* 【高度/大小👁会影响最新消息的底部留白，不可调太高，宽度拉不动再调高一点】 */
background-image: url("https://iili.io/qRq3xB2.png"); 
  background-size: contain; 
  background-repeat: no-repeat;
  z-index: -4; 
  pointer-events: none; 
}





/*——————🍃文本边距——————*/

 .mes_text,
.mes_reasoning {
    font-weight: 500; 
    line-height: 1.9; /* 行高 */
    text-align: justify; 
    text-justify: inter-word; 
    overflow-wrap: anywhere;
    hyphens: auto; 

    /* 优化后的间距系统 */
    --top-padding: 19.8rem;    /* 顶部 */
    --bottom-padding: 0.5rem; /* 底部 */
    --left-padding: 0.3rem;  /* 左侧 */
    --right-padding: 1rem; /* 右侧 */


    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);

    max-width: 100ch;

    margin: 0 auto; 

    /* 高级排版增强 */
    font-kerning: normal; 
    letter-spacing: 0.01em; 
    text-rendering: optimizeLegibility; 
}

/*@咩野老师*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}
/* ==============================================
🦋气泡拼接结束🍃头像美化开始============================================== */


/*⭕️头像框*/
.mesAvatarWrapper {
  position: absolute;
  top: -147px;
  left: 48.9%;
  transform: translateX(-50%);
  z-index: -1;
  width: 70px;  
  height: 70px; 
  overflow: visible; 
}

/* ⭕️头像框位置与大小调整核心 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 113%;/* 【上下】 */
  left: 60%;/* 【左右】 */
  width: 246.5%;  /* 【框宽度】 */
  height: 273.5%; /* 【框高度】 */
  display: block;

  /* ⭕️头像框链接放置处 */
  background-image: url('https://iili.io/qRq33dX.png');/*←🍃*/
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -50%);
  z-index: 1; 

}

.mesAvatarWrapper img {
  position: relative;
  z-index: -1; 
}

/* ⭕️头像位置 */
.mesAvatarWrapper {
  position: absolute;
  top: -1px;           /* 【负值向上】 */
  left: 27%;            /* 【头像左右】 */
  transform: translateX(-50%);
  z-index: -1;
    filter: 
    saturate(1) !important;/*头像饱和度*/
}

/* ⭕️头像尺寸*/
.mesAvatarWrapper .avatar {
  /* 🍃头像尺寸 */
  width: 105.4px;           /* 宽度 */
  height: 143.5px;          /* 高度 */
  transform: rotate(8deg); /* 旋转 */
}
.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ⭕user设置页面/角色选择头像美化⭕*/
/*收藏头像黄圈隐藏、名字颜色修改@Little YE*/
.character_select.is_fav .avatar {
