}
.avatar img {
    border: 2px solid #fff; /* 头像描边 */
box-shadow:0px 2px 1px rgba(0, 0, 0, 0.2);
}
.avatar-container{
filter: 
    saturate(1) !important;}
.bogus_folder_select,
.character_select{
filter: 
    saturate(1) !important;}

