}


/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  border-left:2px solid #3c3a39 !important;
  /* 横向重复 */
background: url('') repeat-y !important;
background-size: 100% auto !important;repeat-y !important;
  color: #3c3a39 !important; 
  box-shadow: 
    neno;
  border-radius: 0px !important; 

}
.mes_text blockquote,
.mes_reasoning blockquote {
    padding-left: 7px;
