/* ——自定义文本选中样式@时鸢 —— */
::selection {
    background-color: rgba(60, 58, 57,0.8); 
    color: #ffefc9; 
    text-shadow: none;
}
::-moz-selection {
    background-color: rgba(60, 58, 57,0.8);
    color: #ffefc9; 
    text-shadow: none;
}
input::selection,
textarea::selection {
    background-color: rgba(60, 58, 57,0.8);
    color: #ffefc9; 
}

/* ==============================================
🦋文字效果美化结束🍃零碎美化开始============================================== */

/*—— 🍃楼层 ——*/


.mes .mesIDDisplay {
    position: fixed;
    top: 32px;
    left: 165px;                    /* 从左侧开始定位 */
  transform: none;            /* 移除所有变换效果 */
    z-index: 2;
    margin-top: 0px;
    text-align: left;           /* 文字左对齐 */
    width: auto;                /* 宽度自适应内容 */
    white-space: nowrap;        /* 防止文字换行 */
    padding: 0 10px;            /* 添加左右内边距 */
    display: inline-flex; 
    align-items: center;  
    gap: 2px;            /* 【左右文字间距】 */

    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.8);
    font-weight: 300;
    color: #927d62;      /* 【颜料🎨】【主文字颜色】 */
transform: rotate(-6deg); /* 旋转 */
}


/* 左侧文字 */
.mes .mesIDDisplay::before {
    content: var(--left-text, ""); /* 【左侧文字内容】 */
    white-space: nowrap;  
    color: var(--left-color, #FFC67F); /* 【颜料🎨】【左侧文字颜色】 */
    font-weight: 300;
}

/* 右侧文字 */
.mes .mesIDDisplay::after {
    content: var(--right-text, ""); /* 【右侧文字内容】 */
    white-space: nowrap;  
    color: var(--right-color, #FFC67F); /* 【颜料🎨】【右侧文字颜色】 */
    font-weight: 300;
}

/*—— 🍃基础信息【时间戳、角色昵称等】 ——*/

/* ⭕️消息文字上边距留白核心调整 */
.mes_block {
  position: relative;
  margin-top: -120px;  
  overflow: visible;
}

/* ⭕️角色名称核心调整 */
.mes_block .ch_name {
  position: relative;
  top:210px; /* 上下 */
