  min-height: 0px;
  z-index: 10; 
  font-size: 0.9em;
  font-weight: 300;
  letter-spacing: 0.9px;
  white-space: nowrap;
  transform: rotate(-6deg); /* 旋转 */
  color: #927d62 !important; 
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
    font-family: "Kingnammm Maiyuan 2", "荆南麦圆 2", sans-serif;
    font-weight: normal;
}
/* 左侧文字 */
.mes_block .ch_name::before {
  content: "";       /*左侧文字 */
  font-size: 1em;
  color: #000;            /* 左侧文字颜色 */
  display: inline;
  padding-right: -0px;        /* 右侧间距（分隔时间戳） */
  pointer-events: none;
}



/* ⭕️编辑按钮核心调整 */
.mes_buttons {
  position: relative;
  top: 20px; /*上下*/
  left: -150px;/*左右*/
  z-index: 30;
  padding: 20px; 
  min-height: 36px;
  box-sizing: border-box;
  transform: rotate(6deg); /* 旋转 */
}

.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
    filter: none; /*移除阴影*/
    transition: 0.3s ease-in-out;

    /* ⭕编辑菜单位置核心调整⭕ */
    position: relative;
    top: 117px;  /* 负数上移 | 正数下移  */
    right: 270px;   /* 负数右移 | 正数左移  */

  transform: rotate(5deg); /* 旋转 */
}
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
}
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: none !important;
    /* ⭕设置省略号菜单颜色 */
    color: #926754 !important;
opacity: 1 !important; 
}

/*—— 计时器&字符——*/
.mes {
  position: relative; 
}

.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; 
  z-index: 3; 
  cursor: default;
opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 0.8);/*文字大小*/
  font-weight: 300;/*文字粗细*/
  padding: 0;
  top: var(--element-top, 240px);
  left: var(--element-left, 50%);
  transform: translateX(var(--element-translate, -50%));
transform: rotate(-6deg); /* 旋转 */
}


/* === ⭕️计时器核心 === */
.mes .mes_timer {
  --element-top: var(--counter-top,86px); /* 【🍃計時器计数器上下】 */
  --element-left: var(--counter-left, 263%); /* 【🍃计时器计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #927d62; /* 【🍃计时器颜色】 */
    --counter-prefix-color: #C5D5DF; /* 【🍃前缀颜色】 */
  --counter-suffix-color: #C5D5DF; /* 【🍃后缀颜色】 */
  color: var(--counter-main-color);
}

/* 计时器文字控制 */
.mes .mes_timer::before {
content: var(--timer-prefix); /* 前缀文字 */
  color: var(--timer-prefix-color);
  padding-right: 9px;
}
.mes .mes_timer::after {
  content: var(--timer-suffix); /* 后缀文字 */
  color: var(--timer-suffix-color);
  padding-left: 0px;
}

/* === 字符计数器单独设置 === */
.mes .tokenCounterDisplay {
  text-align: left;
  --element-top: var(--counter-top, 58px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 257%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #927d62; /* 【🍃计数器颜色】 */
    --counter-prefix-color: #C5D5DF; /* 【🍃前缀颜色】 */
  --counter-suffix-color: #C5D5DF; /* 【🍃后缀颜色】 */
  color: var(--counter-main-color);

}

.mes .tokenCounterDisplay::before {
  content: var(--counter-prefix); /* 前缀文字 */
  color: var(--counter-prefix-color);
  padding-right: 0px;
}
.mes .tokenCounterDisplay::after {
  content: var(--counter-suffix); /* 后缀文字 */
  color: var(--counter-suffix-color);
  padding-left: 0px;
}
