    padding: 10px 15px 10px 50px; /* 调整内边距，上-右-下-左 */
    min-height: 30px;/* 通知框最小高度 */ 
    max-width: 260px;/* 通知框最大宽度 */
backdrop-filter: blur(20px) !important;
transform: rotate(-2deg); /* 旋转 */

}

.toast::before {
    content: '';
    position: absolute;
    left: 10px;/* 设置图标距离左边的位置 */
    top: 50%;/* 垂直居中对齐 */
    transform: translateY(-50%);
    width: 33px;/* 宽度 */
    height: 33px;/* 高度 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
opacity: 1 !important;

}

/* 成功 (Success) 通知的自定义图标 */
.toast-success::before {
    background-image: url("https://iili.io/qRq3VYF.png");
}

/* 错误 (Error) 通知的自定义图标 */
.toast-error::before {
    background-image: url("https://iili.io/qRq31EB.png");
}

/* 信息 (Info) 通知的自定义图标 */
.toast-info::before {
    background-image: url("https://iili.io/qRq3VYF.png");
}

/* 警告 (Warning) 通知的自定义图标 */
.toast-warning::before {
    background-image: url("https://iili.io/qRq31EB.png");
}

/* 消息文字样式 */
.toast-title {
    color: #3c3a39;
    font-size: 12px;
}

.toast-message {
    color: #3c3a39 !important ;
    font-size: 12px !important ;
} 

